    /// <summary>
    /// TLS server functionality.
    /// </summary>
    public interface TLSServer
    {
        /// <summary>
        /// This operation assigns a key pair and certificate along with a certification path (certificate
        /// chain) to the TLS server on the device. The TLS server shall use this information for key exchange
        /// during the TLS handshake, particularly for constructing server certificate messages as specified in
        /// RFC 4346 and RFC 2246. Certification paths are identified by their certification path IDs in the
        /// keystore. The first certificate in the certification path must be the TLS server certificate. Since
        /// each certificate has exactly one associated key pair, a reference to the key pair that is associated
        /// with the server certificate is not supplied explicitly. Devices shall obtain the private key or
        /// results of operations under the private key by suitable internal interaction with the keystore. If a
        /// device chooses to perform a TLS key exchange based on the supplied certification path, it shall use
        /// the key pair that is associated with the server certificate for key exchange and transmit the
        /// certification path to TLS clients as-is, i.e., the device shall not check conformance of the
        /// certification path to RFC 4346 norRFC 2246. In order to use the server certificate during the TLS
        /// handshake, the corresponding private key is required. Therefore, if the key pair that is associated
        /// with the server certificate, i.e., the first certificate in the certification path, does not have an
        /// associated private key, the NoPrivateKey fault is produced and the certification path is not
        /// associated to the TLS server. A TLS server may present different certification paths to different
        /// clients during the TLS handshake instead of presenting the same certification path to all clients.
        /// Therefore more than one certification path may be assigned to the TLS server. If the maximum number
        /// of certification paths that may be assigned to the TLS server simultaneously is reached, the device
        /// shall generate a MaximumNumberOfCertificationPathsReached fault and the requested certification path
        /// shall not be assigned to the TLS server.
        /// </summary>
        System.Threading.Tasks.Task<AddServerCertificateAssignmentResponse> AddServerCertificateAssignmentAsync(AddServerCertificateAssignmentRequest request, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// Calls the operation with its request members as arguments, instead of building the request.
        /// </summary>
        System.Threading.Tasks.Task<AddServerCertificateAssignmentResponse> AddServerCertificateAssignmentAsync(string CertificationPathID, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// This operation removes a key pair and certificate assignment (including certification path) to the
        /// TLS server on the device. Certification paths are identified using certification path IDs. If the
        /// supplied certification path ID is not associated to the TLS server, an InvalidArgVal fault is
        /// produced.
        /// </summary>
        System.Threading.Tasks.Task<RemoveServerCertificateAssignmentResponse> RemoveServerCertificateAssignmentAsync(RemoveServerCertificateAssignmentRequest request, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// Calls the operation with its request members as arguments, instead of building the request.
        /// </summary>
        System.Threading.Tasks.Task<RemoveServerCertificateAssignmentResponse> RemoveServerCertificateAssignmentAsync(string CertificationPathID, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// This operation replaces an existing key pair and certificate assignment to the TLS server on the
        /// device by a new key pair and certificate assignment (including certification paths). After the
        /// replacement, the TLS server shall use the new certificate and certification path exactly in those
        /// cases in which it would have used the old certificate and certification path. Therefore, especially
        /// in the case that several server certificates are assigned to the TLS server, clients that wish to
        /// replace an old certificate assignment by a new assignment should use this operation instead of a
        /// combination of the Add TLS Server Certificate Assignment and the Remove TLS Server Certificate
        /// Assignment operations. Certification paths are identified using certification path IDs. If the
        /// supplied old certification path ID is not associated to the TLS server, or no certification path
        /// exists under the new certification path ID, the corresponding InvalidArgVal faults are produced and
        /// the associations are unchanged. The first certificate in the new certification path must be the TLS
        /// server certificate. Since each certificate has exactly one associated key pair, a reference to the
        /// key pair that is associated with the new server certificate is not supplied explicitly. Devices
        /// shall obtain the private key or results of operations under the private key by suitable internal
        /// interaction with the keystore. If a device chooses to perform a TLS key exchange based on the new
        /// certification path, it shall use the key pair that is associated with the server certificate for key
        /// exchange and transmit the certification path to TLS clients as-is, i.e., the device shall not check
        /// conformance of the certification path to RFC 4346 norRFC 2246. In order to use the server
        /// certificate during the TLS handshake, the corresponding private key is required. Therefore, if the
        /// key pair that is associated with the server certificate, i.e., the first certificate in the
        /// certification path, does not have an associated private key, the NoPrivateKey fault is produced and
        /// the certification path is not associated to the TLS server.
        /// </summary>
        System.Threading.Tasks.Task<ReplaceServerCertificateAssignmentResponse> ReplaceServerCertificateAssignmentAsync(ReplaceServerCertificateAssignmentRequest request, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// Calls the operation with its request members as arguments, instead of building the request.
        /// </summary>
        System.Threading.Tasks.Task<ReplaceServerCertificateAssignmentResponse> ReplaceServerCertificateAssignmentAsync(string OldCertificationPathID, string NewCertificationPathID, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

        /// <summary>
        /// This operation sets the version(s) of TLS which the device shall use. Valid values are taken from
        /// the TLSServerSupported capability. A client initiates a TLS session by sending a ClientHello with
        /// the hightest TLS version it supports. This suggests to the server that the client can accept any TLS
        /// version up to and including that version. The server then chooses the TLS version to use. This is
        /// generally the highest TLS version the server supports that is within the range of the client. For
        /// example, if a ClientHello indicates TLS version 1.1, the server can proceed with TLS 1.0 or TLS 1.1.
        /// In the event that an ONVIF installation wishes to disable certain version(s) of TLS, it may do so
        /// with this operation. For example, to disable TLS 1.0 on a device signaling support for TLS versions
        /// 1.0, 1.1, and 1.2, the enabled version list may be set to "1.1 1.2", omitting 1.0. If a client then
        /// attempts to connect with a ClientHello containing TLS 1.0, the server shall send a
        /// "protocol_version" alert message and close the connection. This handshake indicates to the client
        /// that TLS 1.0 is not supported by the server. The client must try again with a higher TLS version
        /// suggestion. An empty list is not permitted. Disabling all versions of TLS is not the intent of this
        /// operation. See AddServerCertificateAssignment and RemoveServerCertificateAssignment.
        /// </summary>
        System.Threading.Tasks.Task<SetEnabledTLSVersionsResponse> SetEnabledTLSVersionsAsync(SetEnabledTLSVersionsRequest request, System.Threading.CancellationToken cancellationToken = default(System.Threading.CancellationToken));

